<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount,nextTick} from 'vue'
import {Download,X,LoaderCircle,Info} from 'lucide-vue-next'
import {api,query,downloadFile} from './api'
import UiSelect from './UiSelect.vue'
import {teachingPeriodRule} from './teachingCalendar'
import PageTable from './PageTable.vue'
import AnalysisTableHeader from './AnalysisTableHeader.vue'
import FillingState from './FillingState.vue'
import {usePaginationScroll} from './usePaginationScroll'
type Item=Record<string,any>
const props=defineProps<{year:number,term:string,period:number,teacher:string,user:Item,meta:Item}>()
const emit=defineEmits<{layout:[]}>()
const week=ref(props.period),teacher=ref(props.teacher),grade=ref(''),metric=ref('completion'),dimension=ref('teacher'),sort=ref('name'),direction=ref<'asc'|'desc'>('asc')
const weekOptions=computed(()=>[...new Set([...Array.from({length:teachingPeriodRule(props.meta,'habit',props.term).periods},(_,i)=>i+1),props.period])].map(value=>({value,label:`第 ${value} 周 · ${props.year}${props.term}${value>teachingPeriodRule(props.meta,'habit',props.term).periods?' · 历史':''}`})))
const result=ref<Item|null>(null),loading=ref(false),error=ref(''),downloadBusy=ref(false),reports=ref<HTMLDetailsElement>(),groupPage=ref(1)
const analysisRoot=ref<HTMLElement>(),drillBody=ref<HTMLElement>()
const groupPagination=usePaginationScroll(()=>analysisRoot.value?.querySelector<HTMLElement>('.wa-comparison')?.parentElement||undefined),drillPagination=usePaginationScroll(()=>drillBody.value?.querySelector<HTMLElement>('.wa-tablewrap')||undefined)
const dialog=ref<HTMLDialogElement>(),drillFilter=ref<Item|null>(null),drillResult=ref<Item|null>(null),drillLoading=ref(false),drillError=ref(''),drillPage=ref(1)
const metrics=[{id:'completion',label:'作业完成度'},{id:'wechat',label:'微信打卡率'},{id:'average',label:'两项平均'},{id:'reading',label:'朗读分'},{id:'stars',label:'星币汇总'}]
const dimensions=[{id:'teacher',label:'按教师',name:'教师'},{id:'grade',label:'按年级',name:'年级'},{id:'class',label:'按班级',name:'班级'}]
const ranks=['A+','A','B','C','D'],colors=['#347959','#70a88c','#6a96d3','#d5ad63','#c98b87']
const summary=computed(()=>result.value?.summary),metricName=computed(()=>metrics.find(m=>m.id===metric.value)!.label),groupName=computed(()=>dimensions.find(d=>d.id===dimension.value)!.name)
const teacherName=computed(()=>props.meta.teachers.find((t:Item)=>String(t.id)===teacher.value)?.name||'全部授权教师')
const scopeLabel=computed(()=>`${props.year}年${props.term}季 · 第 ${week.value} 周 · ${teacherName.value} · ${grade.value||'全部年级'}`)
const gradeOptions=computed(()=>[{value:'',label:'全部年级'},...[...new Set<string>([...(result.value?.grades||[]),...(grade.value?[grade.value]:[])])].map(g=>({value:g,label:g}))])
const groupPages=computed(()=>Math.max(1,Math.ceil((result.value?.groups.length||0)/20))),groups=computed(()=>result.value?.groups.slice((groupPage.value-1)*20,groupPage.value*20)||[])
const drillPages=computed(()=>Math.max(1,Math.ceil((drillResult.value?.total||0)/30)))
const columns=computed(()=>[{key:'name',label:groupName.value,type:'text'},{key:'coverage',label:'已填 / 可见',type:'number'},{key:metric.value==='stars'?'stars':'average',label:metric.value==='stars'?'星币合计':'平均值',type:'number'},...(metric.value==='stars'?[{key:'awarded',label:'获奖学生',type:'number'},{key:'four_stars',label:'4枚学生',type:'number'}]:ranks.map(r=>({key:r,label:r,type:'number'})))])
function params(){return {kind:'habit',year:props.year,term:props.term,period:week.value,teacher_id:teacher.value,grades:grade.value,metric:metric.value,dimension:dimension.value,analysis_sort:sort.value,direction:direction.value}}
function value(v:any,unit=''){return v===null||v===undefined?'—':v+unit}
function closeDrill(){drillPagination.cancel();++drillVersion;dialog.value?.close();drillFilter.value=null;drillResult.value=null}
let version=0,drillVersion=0
async function load(){const current=++version;loading.value=true;error.value='';try{const data=await api(`teaching/workbench/analysis/?${query(params())}`);if(current===version){emit('layout');result.value=data}}catch(e){if(current===version){result.value=null;error.value=(e as Error).message}}finally{if(current===version)loading.value=false}}
watch(()=>[props.year,props.term,props.period],()=>{groupPagination.cancel();week.value=props.period;grade.value='';closeDrill();groupPage.value=1;void load()})
watch(()=>props.teacher,v=>teacher.value=v)
watch([week,teacher,grade,metric,dimension],()=>{groupPagination.cancel();closeDrill();groupPage.value=1;sort.value='name';direction.value='asc';void load()})
watch([sort,direction],()=>{groupPagination.cancel();groupPage.value=1;void load()})
function sortBy(key:string){const first=key==='name'?'asc':'desc';if(sort.value!==key){sort.value=key;direction.value=first}else if(direction.value===first)direction.value=first==='asc'?'desc':'asc';else{sort.value='name';direction.value='asc'}}
async function openStudents(bucket:string,group?:Item){if(loading.value)return;drillFilter.value={bucket,group_key:group?.key||'',label:group?.label||'',subtitle:group?.subtitle||''};drillPage.value=1;drillResult.value=null;dialog.value?.showModal();await loadDrill()}
async function loadDrill(ticket?:ReturnType<typeof drillPagination.prepare>){if(!drillFilter.value)return;const current=++drillVersion;drillLoading.value=true;drillError.value='';try{const data=await api(`teaching/workbench/analysis/students/?${query({...params(),bucket:drillFilter.value.bucket,group_key:drillFilter.value.group_key,page:drillPage.value,page_size:30})}`);if(current===drillVersion){drillResult.value=data;await nextTick();if(ticket)void drillPagination.finish(ticket,()=>current===drillVersion&&!!dialog.value?.open)}}catch(e){if(current===drillVersion){drillError.value=(e as Error).message;drillPagination.cancel()}}finally{if(current===drillVersion)drillLoading.value=false}}
function turnDrill(change:number){if(drillLoading.value)return;const ticket=drillPagination.prepare();drillPage.value+=change;void loadDrill(ticket)}
async function turnGroup(change:number){const ticket=groupPagination.prepare(),scope=JSON.stringify(params());groupPage.value+=change;const next=groupPage.value;await nextTick();void groupPagination.finish(ticket,()=>groupPage.value===next&&scope===JSON.stringify(params()))}
const drillTitle=computed(()=>{const bucket=drillFilter.value?.bucket;return bucket==='unfilled'?'未填学生':bucket==='blank'?`${metricName.value} · 指标未填`:bucket==='all'?'学生明细':bucket==='awarded'?'获得星币的学生':bucket==='four_stars'?'获得4枚的学生':`${metricName.value} · ${bucket} 等级学生`})
async function download(mode:string){if(downloadBusy.value||loading.value)return;downloadBusy.value=true;error.value='';if(reports.value)reports.value.open=false;try{const scope={kind:'habit',year:props.year,term:props.term,period:week.value,teacher_id:teacher.value,class_type:grade.value};const path=mode==='current'?`teaching/workbench/analysis/export/?${query(params())}`:`teaching/export/?${query({...scope,mode,...(mode==='final'?{period:'',teacher_id:props.user.role==='teacher'?props.user.id:teacher.value}:{})})}`;await downloadFile(path)}catch(e){error.value=(e as Error).message}finally{downloadBusy.value=false}}
onBeforeUnmount(()=>{++version;++drillVersion})
void load()
</script>
<template>
 <div ref="analysisRoot" class="weekly-analysis-focus" :aria-busy="loading">
  <div class="wa-panelhead"><h2>本周表现分析 <span v-if="loading" class="wa-update-status" role="status">更新中…</span></h2><div class="wa-panel-actions"><details class="wa-context-help"><summary aria-label="统计说明" title="统计说明"><Info :size="17"/></summary><div><strong>{{scopeLabel}}</strong><template v-if="result"><p>{{result.policy}}</p><p>{{result.coverage_note}} {{result.notice}}</p></template></div></details><details ref="reports" class="wa-report-menu"><summary>报表下载 <Download :size="14"/></summary><div><button :disabled="loading||downloadBusy" @click="download('current')">当前分析视图<small>当前范围、指标和分组</small></button><button :disabled="loading||downloadBusy" @click="download('analysis')">原口径分析总表<small>保留空等级计D的原规则</small></button><button :disabled="loading||downloadBusy" @click="download('stars')">星币总表<small>当前教师及年级范围</small></button><button v-if="user.role==='teacher'||teacher" :disabled="loading||downloadBusy" @click="download('final')">{{user.role==='teacher'?'我的期末数据':'该教师期末数据'}}<small>{{user.role==='teacher'?'本人、所选年级':'所选教师及年级'}} · 整个学期</small></button></div></details></div></div>
  <div class="wa-controls"><label>教学周期<UiSelect v-model="week" aria-label="分析教学周期" :options="weekOptions"/></label><label>教师范围<UiSelect v-model="teacher" aria-label="分析教师范围" :options="[{value:'',label:'全部授权教师'},...meta.teachers.map((t:Item)=>({value:String(t.id),label:t.name}))]"/></label><label>年级<UiSelect v-model="grade" aria-label="分析年级" :options="gradeOptions"/></label></div>
  <p v-if="error" class="wa-error" role="alert">{{error}}</p><p v-if="!result&&loading" class="wa-loading"><LoaderCircle class="spin" :size="17"/>正在统计完整授权数据…</p>
  <template v-if="result">
   <div class="wa-coverage"><span>已填 <strong>{{summary.filled_count}} / {{summary.visible_count}}</strong><small class="wa-scope-label">可见学生</small></span><button v-if="summary.unfilled_count" class="wa-missinglink" :disabled="loading" :aria-label="`查看${summary.unfilled_count}名未填学生`" @click="openStudents('unfilled')">未填 {{summary.unfilled_count}} ›</button><span class="wa-range">{{summary.class_count}} 个班<span v-if="summary.outside_count"> · 名单外 {{summary.outside_count}}</span></span></div>
   <div class="wa-metrics" role="group" aria-label="选择分析指标"><button v-for="m in metrics" :key="m.id" :aria-pressed="metric===m.id" @click="metric=m.id">{{m.label}}</button></div>
   <div class="wa-chart" :class="{'wa-updating':loading}">
    <template v-if="metric==='stars'"><div class="wa-starstats"><span><strong>{{summary.stars}}</strong>枚星币</span><button :disabled="loading||!summary.awarded_count" @click="openStudents('awarded')"><strong>{{summary.awarded_count}}</strong>人获奖</button><button :disabled="loading||!summary.four_star_count" @click="openStudents('four_stars')"><strong>{{summary.four_star_count}}</strong>人获4枚</button></div></template>
    <template v-else><div class="wa-charthead"><div class="wa-valid-count"><h3>等级分布</h3><span>有效 {{summary.valid_count}} 人</span></div><div class="wa-mean">平均<strong>{{value(summary.average,result.unit)}}</strong></div></div><template v-if="summary.valid_count"><div class="wa-stack" role="img" :aria-label="`${metricName}：`+ranks.map(r=>`${r} ${summary.ranks[r].count}人`).join('，')"><span v-for="(r,i) in ranks" :key="r" :style="{flex:summary.ranks[r].count,background:colors[i]}"/></div><div class="wa-grades"><button v-for="(r,i) in ranks" :key="r" class="wa-grade" :disabled="loading||!summary.ranks[r].count" :aria-label="`查看${r}等级的${summary.ranks[r].count}名学生`" @click="openStudents(r)"><span class="wa-grade-label"><i :style="{background:colors[i]}"/>{{r}}</span><strong>{{summary.ranks[r].count}} 人</strong><small>{{value(summary.ranks[r].rate,'%')}}</small></button></div></template><p v-else class="wa-empty">暂无数据</p></template>
    <button v-if="summary.metric_missing_count>0&&summary.metric_missing_count!==summary.unfilled_count" class="wa-link wa-metric-missing" :disabled="loading" @click="openStudents('blank')">本指标缺 {{summary.metric_missing_count}} 人</button>
   </div>
   <div class="wa-grouphead"><h3>{{groupName}}对比</h3><div class="wa-segments" role="group" aria-label="比较维度"><button v-for="d in dimensions" :key="d.id" :aria-pressed="dimension===d.id" @click="dimension=d.id">{{d.label}}</button></div></div>
   <PageTable class="wa-tablewrap" label="周习惯分组分析" :has-rows="!!groups.length&&!loading" :class="{'wa-updating':loading}"><template #default="{docked}"><table class="wa-comparison" aria-label="分组分析对照"><AnalysisTableHeader :columns="columns" :sort="sort" :direction="direction" :inactive="docked" @sort="sortBy"/><tbody><tr v-for="g in groups" :key="g.key" :data-analysis-group="g.key"><td><strong>{{g.label}}<span v-if="dimension==='class'&&typeof g.is_experimental==='boolean'" class="wa-cohort">{{g.is_experimental?'实':'普'}}</span></strong><small class="wa-row-meta">{{g.subtitle}}</small></td><td><button v-if="g.unfilled_count" class="wa-ratio-missing" :disabled="loading" :aria-label="`查看${g.label}的${g.unfilled_count}名未填学生`" @click="openStudents('unfilled',g)">{{g.filled_count}} / {{g.visible_count}}</button><span v-else>{{g.filled_count}} / {{g.visible_count}}</span></td><td>{{metric==='stars'?value(g.stars,'枚'):value(g.average,result.unit)}}</td><template v-if="metric==='stars'"><td><button class="wa-cellnumber" :disabled="loading||!g.awarded_count" @click="openStudents('awarded',g)">{{g.awarded_count}}</button></td><td><button class="wa-cellnumber" :disabled="loading||!g.four_star_count" @click="openStudents('four_stars',g)">{{g.four_star_count}}</button></td></template><td v-for="r in metric==='stars'?[]:ranks" :key="r"><button class="wa-cellnumber" :disabled="loading||!g.ranks[r].count" :aria-label="`查看${g.label}${r}等级的${g.ranks[r].count}名学生`" :title="`占本组有效学生 ${value(g.ranks[r].rate,'%')}`" @click="openStudents(r,g)">{{g.ranks[r].count}}</button></td><td><button class="wa-link" :disabled="loading" :aria-label="`查看${g.label}学生`" @click="openStudents('all',g)">查看 ›</button></td></tr><tr v-if="!result.groups.length"><td :colspan="columns.length+1" class="wa-empty">暂无学生</td></tr></tbody></table></template><template #header><AnalysisTableHeader :columns="columns" :sort="sort" :direction="direction" @sort="sortBy"/></template></PageTable>
   <div v-if="groupPages>1" class="wa-group-pages"><span>{{result.groups.length}} 组</span><div><button class="btn small" :disabled="groupPage<=1||loading" @click="turnGroup(-1)">上一页</button><span>{{groupPage}} / {{groupPages}}</span><button class="btn small" :disabled="groupPage>=groupPages||loading" @click="turnGroup(1)">下一页</button></div></div>
  </template>
  <dialog ref="dialog" class="wa-dialog" aria-label="分析学生明细" @close="closeDrill"><div class="wa-dialoghead"><div><h2>{{drillTitle}}</h2><p>{{scopeLabel}}<span v-if="drillFilter?.label"> · {{drillFilter.label}} · {{drillFilter.subtitle}}</span></p></div><button class="icon-button" aria-label="返回分析" @click="closeDrill"><X :size="20"/></button></div><div ref="drillBody" class="wa-dialogbody" :aria-busy="drillLoading"><p v-if="drillError" class="wa-error" role="alert">{{drillError}}</p><p v-if="drillLoading" class="wa-loading">正在读取学生…</p><div class="wa-tablewrap"><table class="wa-students"><thead><tr><th>学生</th><th>{{metricName}}</th><th>等级 / 状态</th><th>教师 / 班级</th></tr></thead><tbody><tr v-for="s in drillResult?.items||[]" :key="s.key"><td>{{s.name}}<small>{{s.english_name}}<span v-if="s.membership==='outside'"> · 名单外</span></small></td><td>{{value(s.value,result?.unit)}}</td><td><span v-if="metric!=='stars'&&s.rank" class="wa-badge">{{s.rank}}</span><FillingState v-if="!s.filled||metric==='stars'||!s.rank" :filled="s.filled"/></td><td>{{s.teacher}}<small>{{s.schedule}} · {{s.grade}}<span v-if="typeof s.is_experimental==='boolean'" class="wa-cohort">{{s.is_experimental?'实':'普'}}</span></small></td></tr><tr v-if="!drillLoading&&!drillResult?.total"><td colspan="4" class="wa-empty">没有符合条件的学生。</td></tr></tbody></table></div></div><div class="wa-dialogfoot"><span>{{drillResult?.total||0}} 名学生</span><div><button class="btn small" :disabled="drillLoading||drillPage<=1" @click="turnDrill(-1)">上一页</button><span>{{drillPage}} / {{drillPages}}</span><button class="btn small" :disabled="drillLoading||drillPage>=drillPages" @click="turnDrill(1)">下一页</button><button class="btn" @click="closeDrill">返回分析</button></div></div></dialog>
 </div>
</template>
<style scoped>
